/**
 * Builds src/data/vocabulary.ts from the compact corpus in src/data/corpus/.
 *
 * Corpus format — one word per line, four `|`-separated fields:
 *
 *   term|part of speech|definition|tag, tag
 *
 * Blank lines and lines starting with `#` are ignored. Run `npm run vocab:build`
 * after editing the corpus. The generated file is what the app imports.
 */
import { readdir, readFile, writeFile } from 'node:fs/promises';
import { existsSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const corpusDir = join(root, 'src', 'data', 'corpus');
const outFile = join(root, 'src', 'data', 'vocabulary.ts');

const LEVELS = ['A1', 'A2', 'B1', 'B2', 'C1', 'C2'];
const TARGET_TOTALS = { A1: 800, A2: 800, B1: 750, B2: 650, C1: 0, C2: 0 };

function stripDiacritics(value) {
  return value
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/g, 'd')
    .replace(/Đ/g, 'D');
}

function slugify(value) {
  return stripDiacritics(value)
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

function tsString(value) {
  return `'${value.replace(/\\/g, '\\\\').replace(/'/g, "\\'")}'`;
}

async function readLevel(level) {
  const dir = join(corpusDir, level.toLowerCase());
  if (!existsSync(dir)) return [];

  const files = (await readdir(dir))
    .filter((name) => name.endsWith('.txt'))
    .sort((a, b) => a.localeCompare(b, 'en'));

  const entries = [];
  for (const file of files) {
    const text = await readFile(join(dir, file), 'utf8');
    const lines = text.split(/\r?\n/);
    lines.forEach((raw, lineIndex) => {
      const line = raw.trim();
      if (!line || line.startsWith('#')) return;
      const fields = line.split('|').map((field) => field.trim());
      if (fields.length !== 4) {
        throw new Error(`${level}/${file}:${lineIndex + 1} expected 4 fields, got ${fields.length}`);
      }
      const [term, partOfSpeech, definition, tags] = fields;
      if (!term || !definition) {
        throw new Error(`${level}/${file}:${lineIndex + 1} missing term or definition`);
      }
      entries.push({
        term,
        partOfSpeech,
        definition,
        tags: tags
          .split(',')
          .map((tag) => tag.trim())
          .filter(Boolean),
        source: `${level}/${file}:${lineIndex + 1}`,
      });
    });
  }
  return entries;
}

function renderEntry(entry) {
  const lines = [
    '    {',
    `      id: ${tsString(entry.id)},`,
    `      term: ${tsString(entry.term)},`,
  ];
  if (entry.partOfSpeech) lines.push(`      partOfSpeech: ${tsString(entry.partOfSpeech)},`);
  lines.push(`      definition: ${tsString(entry.definition)},`);
  if (entry.tags.length > 0) {
    lines.push(`      tags: [${entry.tags.map(tsString).join(', ')}],`);
  }
  lines.push('    },');
  return lines.join('\n');
}

const data = {};
const seenTerms = new Map();
const seenIds = new Map();
let failed = false;

for (const level of LEVELS) {
  const entries = await readLevel(level);
  data[level] = entries;

  for (const entry of entries) {
    const termKey = entry.term.toLocaleLowerCase('vi');
    const priorTerm = seenTerms.get(termKey);
    if (priorTerm) {
      console.error(`duplicate term "${entry.term}": ${priorTerm} and ${entry.source}`);
      failed = true;
    } else {
      seenTerms.set(termKey, entry.source);
    }

    const base = slugify(entry.term);
    if (!base) {
      console.error(`cannot build id for "${entry.term}" (${entry.source})`);
      failed = true;
      continue;
    }
    let id = base;
    if (seenIds.has(id)) {
      // Distinct terms can share an unaccented spelling (mắt/mặt, chào/cháo).
      // Keep the first id and add a stable numeric suffix for the rest.
      let counter = 2;
      while (seenIds.has(`${base}-${counter}`)) counter += 1;
      id = `${base}-${counter}`;
    }
    seenIds.set(id, entry.source);
    entry.id = id;
  }
}

const total = LEVELS.reduce((sum, level) => sum + data[level].length, 0);
for (const level of LEVELS) {
  const count = data[level].length;
  const target = TARGET_TOTALS[level];
  if (count !== target) {
    console.error(`${level}: ${count} words (expected ${target})`);
    failed = true;
  }
}
if (total !== 3000) {
  console.error(`total: ${total} words (expected 3000)`);
  failed = true;
}

if (failed) {
  console.error('\nVocabulary build failed. Fix the corpus and run again.');
  process.exit(1);
}

const sections = LEVELS.map((level) => {
  const entries = data[level].map(renderEntry).join('\n');
  if (!entries) return `  ${level}: [],`;
  return `  ${level}: [\n${entries}\n  ],`;
}).join('\n');

const output = `// Generated by scripts/build-vocabulary.mjs from src/data/corpus/ — do not edit by hand.
// Run \`npm run vocab:build\` after changing the corpus.
import type { CEFRLevel, VocabEntry, VocabWord } from '../types';
import { CEFR_LEVELS } from '../types';

/**
 * Vietnamese vocabulary organised by CEFR level. Every entry carries a term, an
 * English definition, a part of speech, and topical tags. C1 and C2 are left
 * empty: this deck focuses on A1–B2 everyday Vietnamese.
 */
export const VOCABULARY: Record<CEFRLevel, VocabEntry[]> = {
${sections}
};

const levelOrder = new Map<CEFRLevel, number>(CEFR_LEVELS.map((level, index) => [level, index]));

export const ALL_WORDS: VocabWord[] = CEFR_LEVELS.flatMap((level) =>
  (VOCABULARY[level] ?? []).map((word) => ({ ...word, level })),
);

export const WORD_BY_ID: Record<string, VocabWord> = Object.fromEntries(
  ALL_WORDS.map((word) => [word.id, word]),
);

export const LEVEL_WORDS: Record<CEFRLevel, VocabWord[]> = Object.fromEntries(
  CEFR_LEVELS.map((level) => [level, ALL_WORDS.filter((word) => word.level === level)]),
) as Record<CEFRLevel, VocabWord[]>;

export const LEVEL_COUNTS: Record<CEFRLevel, number> = Object.fromEntries(
  CEFR_LEVELS.map((level) => [level, LEVEL_WORDS[level].length]),
) as Record<CEFRLevel, number>;

export function sortByLevel(a: VocabWord, b: VocabWord): number {
  return (levelOrder.get(a.level) ?? 0) - (levelOrder.get(b.level) ?? 0);
}
`;

await writeFile(outFile, output, 'utf8');
console.log(
  `Wrote ${outFile}\n` +
    LEVELS.map((level) => `  ${level}: ${data[level].length}`).join('\n') +
    `\n  total: ${total}`,
);
